```js
// 1. process.env: configurações que vêm de fora (sem aparecer no código).
console.log(process.env.HOME); // pasta do usuário
const porta = Number(process.env.PORTA ?? 3000); // padrão se faltar

// 2. process.argv: o que foi digitado na linha de comando.
//    node app.mjs subir --modo=rapido
//    argv: ['node', 'app.mjs', 'subir', '--modo=rapido']
console.log(process.argv.slice(2)); // ['subir', '--modo=rapido']

// 3. process.exitCode: o 'resultado final' do programa (0 = ok).
process.exitCode = 0;
```

```js
// 4. os: o computador onde o programa roda.
import { platform, arch, cpus, availableParallelism } from 'node:os';

console.log(platform());          // 'darwin' no macOS, 'linux', 'win32'...
console.log(arch());              // 'x64', 'arm64'...
console.log(cpus().length);       // núcleos totais
console.log(availableParallelism()); // núcleos que o Node pode usar

// 5. path: montar caminhos do jeito certo em qualquer sistema.
import { join, basename, extname, parse } from 'node:path';

console.log(join('pasta', 'subpasta', 'app.mjs')); // pasta/subpasta/app.mjs
console.log(basename('/a/b/app.mjs')); // app.mjs
console.log(extname('/a/b/app.mjs')); // .mjs
console.log(parse('/a/b/app.mjs').dir); // /a/b
```

A dupla `process.env` + `path.join` é o coração de todo programa de linha de comando: a configuração vem de fora, e os caminhos são montados sem quebrar em nenhum sistema.

